    OR NOT EXISTS(SELECT 1 FROM supabase_migrations.schema_migrations WHERE version='20260830173000' AND name='782_historical_reconciliation_current_head_security_successor' AND statements=ARRAY[
      'Lock and equality-bind the exact live 20260830172000/778 predecessor serialization before replacement',
