 v_trigger_hash:=encode(extensions.digest(convert_to(v_trigger_text,'UTF8'),'sha256'),'hex');
 IF v_trigger_hash IS DISTINCT FROM 'ff68e5580c8a77701eb5f92ef6a0b6ad99a44f0036185e60900a4292775870f1' THEN RAISE EXCEPTION 'PDC_782_1740_TRIGGER_CONTRACT_DRIFT' USING errcode='55000'; END IF;
 SELECT coalesce(string_agg(x.event_object_table||'|'||x.trigger_name||'|'||x.event_manipulation||'|'||x.action_timing||'|'||x.action_statement||'|'||coalesce(encode(extensions.digest(convert_to(pg_get_functiondef(t.tgfoid),'UTF8'),'sha256'),'hex'),'')||'|'||coalesce(pg_get_userbyid(p.proowner),'')||'|'||coalesce(array_to_string(p.proconfig,','),'')||'|'||coalesce((SELECT string_agg(coalesce(pg_get_userbyid(a.grantee),'PUBLIC')||':'||a.privilege_type||':'||a.is_grantable,'|' ORDER BY coalesce(pg_get_userbyid(a.grantee),'PUBLIC'),a.privilege_type,a.is_grantable) FROM aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a),'') ,'|' ORDER BY x.event_object_table,x.trigger_name,x.event_manipulation),'') INTO v_trigger_executor_text FROM information_schema.triggers x JOIN pg_class c ON c.relname=x.event_object_table JOIN pg_namespace n ON n.oid=c.relnamespace AND n.nspname=x.event_object_schema JOIN pg_trigger t ON t.tgrelid=c.oid AND t.tgname=x.trigger_name JOIN pg_proc p ON p.oid=t.tgfoid WHERE x.event_object_schema='public' AND x.event_object_table IN ('ai_email_intake','ai_email_attachments','vehicles','vehicle_work_items','pdc_authenticated_email_operation_lines','vehicle_workshop_line_adjustments','vehicle_parts_updates','workshop_bookings','workshop_booking_assignments','pdc_sublet_bookings','pdc_sublet_booking_instances','pdc_qc_operation_completions_379','pdc_pmb_stoppage_receipts_422','pdc_email_monitor_current_head_compatibility_controls_766','pdc_email_monitor_pilot','pdc_email_monitor_status','pdc_qc_salesperson_update_outbox_399','pdc_rft_transport_email_outbox_734','pdc_sublet_email_update_receipts','pdc_historical_provider_observations_778','pdc_historical_reconciliation_778_receipts');
 v_trigger_executor_hash:=encode(extensions.digest(convert_to(v_trigger_executor_text,'UTF8'),'sha256'),'hex');
